Y = 11
raw = open(BIT,"rb").read()
sync = raw.find(b"\xaa\x99\x55\x66")
pos = sync+4
w32 = lambda o: struct.unpack(">I", raw[o:o+4])[0]
payload_words = None
while pos+4 <= len(raw):
    h = w32(pos); pos += 4
    t = h >> 29; op = (h >> 27) & 3; addr = (h >> 13) & 0x3fff; n = h & 0x3ff
    if t == 1 and op == 1 and n == 0:
        n = w32(pos); pos += 4
    if t == 2:
        if addr == 2:
            payload_words = [w32(pos+4*i) for i in range(n)]
            break
        pos += 4*n
    elif t == 1:
        if addr in (2, 0x0b) and op == 1:
            payload_words = [w32(pos+4*i) for i in range(n)]
            break
        if addr == 0x0d:
            break
        if op == 1:
            pos += 4*n
    else:
        break
NF = len(payload_words)//101
print("frames", NF)
frames = [payload_words[i*101:(i+1)*101] for i in range(NF)]

def hits(base, parity):
    ok = 0; tot = 0
    for fam, srcs in REF.items():
        cnt = 0
        for s, cells in srcs.items():
            good = True
            for off, bit, sense, _p in cells:
                w = frames[base+off][2*(Y % 50)+parity]
                v = (w >> bit) & 1
                if (v == 1) != bool(sense):
                    good = False; break
            if good:
                cnt += 1
        tot += 1
        if cnt == 1:
            ok += 1
    return ok, tot

print("base  p0   p1")
best = []
for base in range(31640, 31800, 4):
    a = hits(base, 0)[0]; b = hits(base, 1)[0]
    best.append((a, base, 0)); best.append((b, base, 1))
best.sort(reverse=True)
print("top10", best[:10])
